local config = {
  ui_story_30680601_1_dialog_content = "Sigh... Apa aku sudah kehabisan uang untuk bulan ini?",
  ui_story_30680601_2_dialog_content = "Saya tidak sering berbelanja di Umbraton...",
  ui_story_30680601_3_dialog_content = "Aku benar-benar ingin membeli permainan papan yang Gronru katakan padaku tentang terakhir kali aku melihatnya.",
  ui_story_30680601_4_dialog_content = "Mungkin saya bisa menggunakan sebagian uang yang diberikan Vice kepada saya untuk persediaan...?",
  ui_story_30680601_5_dialog_content = "Tidak! Tidak mungkin! Beberapa hari yang lalu dia mengajari saya.",
  ui_story_30680601_6_dialog_content = "\"Jangan membelanjakan uang untuk hal-hal yang tidak kita butuhkan! Yang penting saja!\"",
  ui_story_30680601_7_dialog_content = "\"Dengan kebiasaan belanja yang sehat, situasi keuangan kita di Soroz hanya akan menjadi lebih baik dan lebih baik!\"",
  ui_story_30680601_8_dialog_content = "Vice berusaha keras untuk mengawasi pengeluaran kami. Aku seharusnya tidak menyia-nyiakan uang hasil jerih payah kita!",
  ui_story_30680601_9_dialog_content = "Anda, di sana! Jangan bergerak!",
  ui_story_30680601_10_dialog_content = "Ya kamu! Tetap di tempat Anda berada!",
  ui_story_30680601_11_dialog_content = "Hah? Kamu siapa...",
  ui_story_30680601_12_dialog_content = "Tunggu, suara itu... Itu datang dari atasku!",
  ui_story_30680601_13_dialog_content = "Betul sekali! Ini adalah kurir favorit semua orang—Wendy, Spiral Kecepatan Cahaya yang imut dan berani!",
  ui_story_30680601_14_dialog_content = "Adapun Anda, Tuan yang baik, raut wajah Anda mengatakan ada sesuatu yang mengganggu Anda!",
  ui_story_30680601_15_dialog_content = "Mengapa tidak mengambil salah satu koran saya untuk Anda sendiri? Semua jenis kebijaksanaan rahasia terletak tepat di halaman mereka!",
  ui_story_30680601_16_dialog_content = "Saya yakin Anda akan menemukan jawaban atas masalah Anda di salah satu dari sekian banyak artikelnya!",
  ui_story_30680601_17_dialog_content = "... Apa yang terjadi di sini, Wendy? Dan kenapa kamu berpakaian seperti itu?",
  ui_story_30680601_18_dialog_content = "Hah? Nah, jika tidak PlayerName!",
  ui_story_30680601_19_dialog_content = "Pakaianmu...",
  ui_story_30680601_20_option_content = "Ini terlihat luar biasa!",
  ui_story_30680601_21_dialog_content = "Heehee! Mereka tidak memanggilku Spiral Kecepatan Cahaya tanpa alasan!",
  ui_story_30680601_22_option_content = "Ini terlihat lucu!",
  ui_story_30680601_23_dialog_content = "Betulkah? Anda pasti tahu bagaimana menyanjung seorang gadis, PlayerName!",
  ui_story_30680601_24_dialog_content = "Saya memakai seragam ini hanya ketika saya keluar menjual koran!",
  ui_story_30680601_25_dialog_content = "Katakan, aku tidak melihat Vice dimanapun... Bukankah dia bersamamu hari ini?",
  ui_story_30680601_26_dialog_content = "Dia masih di Soroz. Saya datang ke sini untuk membantunya membeli beberapa persediaan.",
  ui_story_30680601_27_dialog_content = "<size=33>Apa?! PlayerName tanpa Wakil... Aku tidak percaya keberuntunganku!</size>",
  ui_story_30680601_28_dialog_content = "Apa yang kau gumamkan pada dirimu sendiri disana...?",
  ui_story_30680601_29_dialog_content = "Heehee... Tidak ada sama sekali! Bagaimanapun, saya bekerja untuk cabang Umbraton dari Serikat Kurir hari ini.",
  ui_story_30680601_30_dialog_content = "Mereka secara khusus meminta saya untuk datang ke sini dan menjual koran.",
  ui_story_30680601_31_dialog_content = "Masuk akal, bukan? Lagi pula, saya luar biasa pintar, berbakat, imut, dan cepat... Saya mendapat banyak pembaca baru dari Gurun Rediesel yang berlangganan mereka!",
  ui_story_30680601_32_dialog_content = "Dan sekarang saya juara penjualan!",
  ui_story_30680601_33_dialog_content = "Mengapa Anda tidak mengambil satu dari tangan saya juga, PlayerName? Hal-hal ini sepadan dengan beratnya dalam emas!",
  ui_story_30680601_34_dialog_content = "T-tunggu…",
  ui_story_30680601_35_dialog_content = "Biarkan saya memikirkannya sebentar... Saya tidak ingin ditipu lagi!",
  ui_story_30680601_36_dialog_content = "Kamu bilang kamu menjual banyak koran di Gurun Rediesel, kan?",
  ui_story_30680601_37_dialog_content = "Sejauh yang saya tahu, satu-satunya orang yang tinggal di sana adalah Kunci Pas Rediesel.",
  ui_story_30680601_38_dialog_content = "Tapi orang-orang itu semua adalah tipe \"pukulan dulu, ajukan pertanyaan tidak pernah\".",
  ui_story_30680601_39_dialog_content = "Apakah ada di antara mereka yang benar-benar membaca koran? Mau tak mau saya berpikir Anda mungkin sedikit melebih-lebihkan...",
  ui_story_30680601_40_dialog_content = "Ide seseorang seperti Brock duduk untuk membaca koran sambil minum teh... Saya rasa saya bahkan tidak bisa membayangkannya.",
  ui_story_30680601_41_dialog_content = "Ya! Kecurigaan Anda 100% benar!",
  ui_story_30680601_42_dialog_content = "Tentu saja, mengirim sembarang orang untuk menjual koran ke Rediesel Wrench akan membuang-buang waktu.",
  ui_story_30680601_43_dialog_content = "Tapi saya selalu percaya bahwa semakin besar tantangannya, semakin terang saya akan bersinar setelah saya mengatasinya!",
  ui_story_30680601_44_dialog_content = "Jangan lupa, saya adalah rudal balistik terbang tinggi dengan kekuatan badai kecil! Ke mana pun saya pergi, saya mencetak tingkat berlangganan lebih dari 99%!",
  ui_story_30680601_45_dialog_content = "Saya menolak untuk percaya bahwa ...",
  ui_story_30680601_46_dialog_content = "Katakan padaku, apakah Sinsa membayar untuk berlangganan?",
  ui_story_30680601_47_dialog_content = "Tentu saja! Sinsa adalah pelanggan pertama saya, sebenarnya!",
  ui_story_30680601_48_dialog_content = "<size=42>Oh, Sinsaaaaaa!</size>",
  ui_story_30680601_49_dialog_content = "Hah? Oh, hai, Wendy.",
  ui_story_30680601_50_dialog_content = "Anda juga tepat waktu. Apakah Anda membawakan saya edisi terbaru Shinnosuke Sinsa?",
  ui_story_30680601_51_dialog_content = "Tidak! Itu tidak akan keluar sampai akhir bulan.",
  ui_story_30680601_52_dialog_content = "Betulkah? Jadi untuk apa kamu di sini? Ada pesan untuk kami atau apa?",
  ui_story_30680601_53_dialog_content = "Salah lagi! Perhatikan sesuatu yang berbeda tentang saya hari ini?",
  ui_story_30680601_54_dialog_content = "Hmm? Hei... Jangan bercanda! Apakah Serikat Kurir mengganti seragam mereka baru-baru ini?",
  ui_story_30680601_55_dialog_content = "Mereka tidak terlihat setengah buruk, sejujurnya... Aku yakin Eve juga akan terlihat sangat imut dengan ini!",
  ui_story_30680601_56_dialog_content = "Tunggu, apa yang aku katakan? Hawa akan terlihat manis dalam segala hal!",
  ui_story_30680601_57_dialog_content = "Bisakah Anda berhenti berbicara tentang Hawa selama beberapa detik, kawan?",
  ui_story_30680601_58_dialog_content = "Saya tidak di sini untuk mengirim surat hari ini.",
  ui_story_30680601_59_dialog_content = "Jadi untuk apa kau di sini?",
  ui_story_30680601_60_dialog_content = "Heehee, jadi... Aku mendapat permintaan khusus dari Serikat Kurir! Saya menjual langganan koran hari ini!",
  ui_story_30680601_61_dialog_content = "Melihat? Lihatlah semua jenis yang berbeda! Aku yakin bahkan ada satu untukmu di sini, Sinsa!",
  ui_story_30680601_62_dialog_content = "Hmm, tidak tertarik.",
  ui_story_30680601_63_dialog_content = "Ini bukan jenis kunci pas Rediesel, Anda tahu?",
  ui_story_30680601_64_dialog_content = "Selain itu... Satu-satunya hal yang saya tertarik untuk membaca adalah Shinnosuke Sinsa.",
  ui_story_30680601_65_dialog_content = "Salah satu pengintaiku baru saja kembali dari pencarian, jadi aku harus pergi melihat apa yang dia temukan. Kembalilah saat mereka mengeluarkan Shinnosuke Sinsa edisi terbaru.",
  ui_story_30680601_66_dialog_content = "Sampai jumpa.",
  ui_story_30680601_67_dialog_content = "... Bagaimana jika saya katakan saya bisa memberikan laporan yang lebih baik dari pramuka Anda?",
  ui_story_30680601_68_dialog_content = "Hah?",
  ui_story_30680601_69_dialog_content = "Tidak percaya padaku? Lihat saja sendiri!",
  ui_story_30680601_70_dialog_content = "Di sini, di halaman ini! Selalu ada kolom menyeluruh tentang perkembangan terbaru tentang Caelestite, serta semua jenis informasi tambahan, dan diterbitkan secara teratur!",
  ui_story_30680601_71_dialog_content = "Dan di sini, Anda dapat melihat tren terbaru di Umbraton dan keadaan pasar!",
  ui_story_30680601_72_dialog_content = "Saya yakin Anda bisa mempelajari segala macam hal yang berguna hanya dari dua artikel ini saja!",
  ui_story_30680601_73_dialog_content = "... Harus diakui, terdengar agak menarik.",
  ui_story_30680601_74_dialog_content = "Tapi bagaimana saya bisa tahu apakah hal-hal di sini benar atau tidak?",
  ui_story_30680601_75_dialog_content = "Mudah! Cukup rujuk silang dengan intel yang dibawa oleh pramuka Anda, dan periksa sendiri faktanya!",
  ui_story_30680601_76_dialog_content = "Oh, dan lihat di sini! Ini kolom mode!",
  ui_story_30680601_77_dialog_content = "Pikirkan saja! Tidak ada gadis yang bisa menolak pakaian dan aksesori imut dari seluruh dunia ini, dan semuanya ada di sini!",
  ui_story_30680601_78_dialog_content = "Saya yakin Hawa benar-benar akan mencintai mereka!",
  ui_story_30680601_79_dialog_content = "B-Benarkah? Anda pikir Eve akan terlibat dalam hal ini...?",
  ui_story_30680601_80_dialog_content = "Oh, pakaian di koran ini terlihat luar biasa! Sungguh selera mode yang Anda miliki, Saudara!",
  ui_story_30680601_81_dialog_content = "Anda benar-benar menyukai mereka, Hawa? Saya akan membeli semuanya untuk Anda!",
  ui_story_30680601_82_dialog_content = "... Berapa banyak jenis yang Anda miliki di sini? Aku akan membawa mereka semua!",
  ui_story_30680601_83_dialog_content = "Senang berbisnis dengan Anda, bos!",
  ui_story_30680601_84_dialog_content = "Menggunakan Hawa untuk membujuk Sinsa... Itu rendah, tapi itu berhasil setiap saat.",
  ui_story_30680601_85_dialog_content = "Juga, apa sih, ada koran yang khusus menguntitku?!",
  ui_story_30680601_86_dialog_content = "Kamu ingin tahu? Maka Anda harus berlangganan!",
  ui_story_30680601_87_dialog_content = "Usaha yang bagus, tapi saya tidak mudah jatuh cinta!",
  ui_story_30680601_88_dialog_content = "Anda beruntung dengan Sinsa, karena dia memiliki titik lemah yang jelas.",
  ui_story_30680601_89_dialog_content = "Itu masih belum membuktikan apa-apa.",
  ui_story_30680601_90_dialog_content = "Coba saya lihat... Bagaimana dengan Fleur? Apakah fanatik mesin itu berlangganan?",
  ui_story_30680601_91_dialog_content = "Tentu saja!",
  ui_story_30680601_92_dialog_content = "Sekarang untuk menyeka pipa minyak...",
  ui_story_30680601_93_dialog_content = "Hei, Fleur!",
  ui_story_30680601_94_dialog_content = "Dan poles baut ini...",
  ui_story_30680601_95_dialog_content = "fleur?",
  ui_story_30680601_96_dialog_content = "Oh, Gathering Storm... Kamu bersinar sangat terang hari ini!",
  ui_story_30680601_97_dialog_content = "Hai! Saya berbicara dengan Anda di sini!",
  ui_story_30680601_98_dialog_content = "Hmm? Oh, hanya kamu, Wendy...",
  ui_story_30680601_99_dialog_content = "Maaf, kurasa aku tidak memperhatikanmu di sana. Saya sedang melakukan perawatan yang sangat penting pada mesin Rediesel Wrench sekarang.",
  ui_story_30680601_100_dialog_content = "Astaga... Tidak apa-apa. Anda harus berlangganan koran ini!",
  ui_story_30680601_101_dialog_content = "Koran?",
  ui_story_30680601_102_dialog_content = "Terima kasih atas tawaranmu, tapi tidak.",
  ui_story_30680601_103_dialog_content = "Saya lebih suka membaca skema dan instruksi manual.",
  ui_story_30680601_104_dialog_content = "Cukup yakin surat kabar tidak menulis tentang apa pun yang saya minati.",
  ui_story_30680601_105_dialog_content = "Ugh... Seharusnya aku tahu Fleur akan lebih menantang daripada Sinsa.",
  ui_story_30680601_106_dialog_content = "... Tunggu, aku mengerti! Anda sedang membersihkan mesin sekarang, kan?",
  ui_story_30680601_107_dialog_content = "Ya, dan lihat saja mereka bersinar! Pernahkah Anda melihat sesuatu yang lebih indah?",
  ui_story_30680601_108_dialog_content = "Mereka berkilau seperti berlian yang tak ternilai, masing-masing dan setiap orang... Tidak ada yang bisa menolak pesona mereka!",
  ui_story_30680601_109_dialog_content = "Anda hanya menunggu!",
  ui_story_30680601_110_dialog_content = "Sedikit gosok di sini, dan sedikit gosok di sana ...",
  ui_story_30680601_111_dialog_content = "A-Apa yang kamu pikir kamu lakukan, Wendy?!",
  ui_story_30680601_112_dialog_content = "Mengumpulkan Storm adalah kebanggaan dan kegembiraanku—",
  ui_story_30680601_113_dialog_content = "Di sana! Lihatlah!",
  ui_story_30680601_114_dialog_content = "Kilauan ini... Bahkan lebih terang dari sebelumnya! Di mana saya meletakkan kacamata pengaman saya?!",
  ui_story_30680601_115_dialog_content = "Dan itulah jenis kilau yang bisa Anda dapatkan dengan menggunakan koran kami!",
  ui_story_30680601_116_dialog_content = "... Aku akan mengambil semua yang kamu punya!",
  ui_story_30680601_117_dialog_content = "Anda benar-benar menipu Fleur untuk membeli koran Anda... untuk digunakan sebagai persediaan pembersih?!",
  ui_story_30680601_118_dialog_content = "Anda harus meminta maaf kepada orang-orang yang bekerja sangat keras menulis untuk surat kabar!",
  ui_story_30680601_119_dialog_content = "Apa masalahnya? Mereka dibayar selama seseorang membeli pekerjaan mereka, bukan?",
  ui_story_30680601_120_dialog_content = "Siapa yang peduli bagaimana pelanggan mereka memilih untuk menggunakannya?",
  ui_story_30680601_121_dialog_content = "Kurasa kau benar juga...",
  ui_story_30680601_122_dialog_content = "Tapi Anda memanfaatkan perasaan Fleur untuk menjual surat kabar Anda! Bahkan jika perasaannya untuk mesin...",
  ui_story_30680601_123_dialog_content = "Bagaimana dengan Roy? Seseorang yang dewasa dan hemat seperti dia tidak mungkin jatuh cinta pada tipuanmu, kan?",
  ui_story_30680601_124_dialog_content = "Hehe, maaf mengecewakan Anda, tetapi dia adalah pelanggan yang puas lainnya!",
  ui_story_30680601_125_dialog_content = "ayooooo!",
  ui_story_30680601_126_dialog_content = "Ayo beli langganan koran, please? Hanya satu!",
  ui_story_30680601_127_dialog_content = "Apa pun yang kau lakukan, Wendy, aku tidak punya waktu untuk itu. Aku sibuk mencuci piring semua orang.",
  ui_story_30680601_128_dialog_content = "Tapi Sinsa membeli seluruh tumpukan dari saya, Roy! Ayo, hanya satu koran yang sangat sedikit!",
  ui_story_30680601_129_dialog_content = "Hahaha... Jika itu masalahnya, maka semakin banyak alasan untuk tidak membeli satu untuk diriku sendiri.",
  ui_story_30680601_130_dialog_content = "Saya hanya bisa meminta salinannya.",
  ui_story_30680601_131_dialog_content = "Ini adalah pilihan yang paling hemat.",
  ui_story_30680601_132_dialog_content = "*Menghela nafas* Meskipun saya benar-benar harus berbicara dengannya tentang kebiasaan belanjanya yang boros dalam waktu dekat...",
  ui_story_30680601_133_dialog_content = "Ugh... Roy adalah kue yang sangat sulit untuk dipecahkan.",
  ui_story_30680601_134_dialog_content = "Tapi Spiral Kecepatan Cahaya tidak menyerah semudah itu!",
  ui_story_30680601_135_dialog_content = "Hidangan ini benar-benar kotor. Dari semua makanan yang bikin ketagihan, kenapa harus hot pot?",
  ui_story_30680601_136_dialog_content = "Dan lihat semua kaleng bekas ini! Sungguh pemborosan yang memalukan.",
  ui_story_30680601_137_dialog_content = "Dan ceret airnya tertutup begitu banyak kerak, saya bahkan tidak bisa melihat logam di dasarnya.",
  ui_story_30680601_138_dialog_content = "Kau…",
  ui_story_30680601_139_dialog_content = "Biar kulihat...",
  ui_story_30680601_140_dialog_content = "Aku punya satu hal, Roy!",
  ui_story_30680601_141_dialog_content = "Beberapa irisan lemon atau bahkan jus lemon, dan penumpukan minyak dan air keras ini dapat dihapus dalam sekejap!",
  ui_story_30680601_142_dialog_content = "Sedangkan untuk kalengnya, Anda bisa memanfaatkannya sebagai tanaman untuk bahan-bahan tertentu, seperti daun bawang atau bawang putih!",
  ui_story_30680601_143_dialog_content = "Bagaimana Anda tahu semua itu?",
  ui_story_30680601_144_dialog_content = "Apakah Serikat Kurir mengajarkan hal-hal ini saat ini?",
  ui_story_30680601_145_dialog_content = "Sama sekali tidak! Di sini, lihat saja ini!",
  ui_story_30680601_146_dialog_content = "Melihat? Seluruh kolom berjudul \"Tips Panas untuk Ibu Rumah Tangga yang Bahagia\"!",
  ui_story_30680601_147_dialog_content = "Katakan apa sekarang? \"Semir sepatu kulit dengan kulit pisang agar terlihat bagus seperti baru...\"",
  ui_story_30680601_148_dialog_content = "Gosok tangan Anda dengan pasta gigi atau lemak babi setelah memotong paprika agar jari Anda tidak terbakar.",
  ui_story_30680601_149_dialog_content = "\"Rendam sweater dalam air panas dan keringkan di udara untuk mengembalikan elastisitas pada lengan dan kerahnya...\"?!",
  ui_story_30680601_150_dialog_content = "I-Ini... Ini luar biasa!",
  ui_story_30680601_151_dialog_content = "Jadi apakah Anda akan berlangganan, Roy?",
  ui_story_30680601_152_dialog_content = "Ya, segera!!",
  ui_story_30680601_153_dialog_content = "Bukan Roy juga... Aku mulai kehilangan kepercayaan pada kenyataan...",
  ui_story_30680601_154_dialog_content = "Keterampilan pemasaran Anda menakutkan, Wendy!",
  ui_story_30680601_155_dialog_content = "Satu-satunya tenaga penjual lain yang bisa bersaing adalah Jomu!",
  ui_story_30680601_156_dialog_content = "Jom, ya?",
  ui_story_30680601_157_dialog_content = "Dia membeli langganan setahun, kau tahu?",
  ui_story_30680601_158_dialog_content = "Oke, tidak mungkin aku percaya itu.",
  ui_story_30680601_159_dialog_content = "Yo, Jomu!",
  ui_story_30680601_160_dialog_content = "Nah, lihat siapa itu! Wendy, burung kecil paling cerdas di seluruh gurun!",
  ui_story_30680601_161_dialog_content = "Padahal, dilihat dari pakaianmu, kurasa kau di sini sebagai penjual, bukan pelanggan... Benar?",
  ui_story_30680601_162_dialog_content = "Heehee, pintar seperti biasa, Jomu!",
  ui_story_30680601_163_dialog_content = "Nah, ketika saingan kuat seperti itu muncul di hadapan Anda, tidak mudah untuk mengabaikannya begitu saja.",
  ui_story_30680601_164_dialog_content = "Tapi saya harus memperingatkan Anda... Trik ruang tamu yang Anda gunakan di Sinsa dan yang lainnya tidak akan berhasil melawan profesional yang paham bisnis seperti saya.",
  ui_story_30680601_165_dialog_content = "Saya tidak akan pernah bermimpi memperlakukan Anda seperti pelanggan biasa, Jomu! Aku punya sesuatu yang lain dalam pikiran. Sesuatu seperti kemitraan?",
  ui_story_30680601_166_dialog_content = "Dari apa yang saya dengar, Anda baru-baru ini menerima kiriman buku, tetapi Anda belum menemukan cara yang cocok untuk menjualnya.",
  ui_story_30680601_167_dialog_content = "Saya dapat memasarkan buku Anda kepada pelanggan yang membeli langganan koran dari saya.",
  ui_story_30680601_168_dialog_content = "Tentu saja, Anda juga perlu berlangganan, dan buku Anda juga memerlukan saluran distribusi yang tepat.",
  ui_story_30680601_169_dialog_content = "Tampaknya Anda telah melakukan penelitian.",
  ui_story_30680601_170_dialog_content = "Dalam hal bisnis, cara terbaik untuk menghasilkan uang adalah ketika semua pihak diuntungkan.",
  ui_story_30680601_171_dialog_content = "Dan di dunia bisnis yang kejam, siapa pun yang memiliki informasi mengendalikan segalanya.",
  ui_story_30680601_172_dialog_content = "Karena Anda telah melakukan penyelidikan menyeluruh atas transaksi saya, saya akan dengan senang hati berbisnis dengan Anda... mitra.",
  ui_story_30680601_173_dialog_content = "Semoga upaya ini dan upaya apa pun di masa depan terbukti bermanfaat bagi kita berdua.",
  ui_story_30680601_174_dialog_content = "Maaf mengecewakan Anda, tetapi persaingan-tebasan-persaingan kami hanya sementara.",
  ui_story_30680601_175_dialog_content = "Setelah saya menyelesaikan tugas ini untuk Serikat Kurir, saya akan kembali ke pekerjaan saya yang biasa!",
  ui_story_30680601_176_dialog_content = "Begitu... Yah, kurasa tidak apa-apa juga. Kurang satu saingan bisnis yang perlu dikhawatirkan.",
  ui_story_30680601_177_dialog_content = "Baiklah, aku menyerah...",
  ui_story_30680601_178_dialog_content = "Saya tidak pernah berpikir Jomu akan menyetujui hal seperti ini. Meskipun saya kira membuat kesepakatan adalah keahliannya.",
  ui_story_30680601_179_dialog_content = "Baik, saya akui: Anda benar-benar jenius penjualan.",
  ui_story_30680601_180_dialog_content = "Akhirnya datang juga, ya? Dalam hal ini, dapatkah saya menarik minat Anda untuk berlangganan surat kabar?",
